	setTestHome(t, testHome)
	t.Setenv(envGitConfigGlobal, "")
	os.Unsetenv(envGitConfigGlobal)
	t.Setenv(envXDGConfigHome, "")
	setTestAppData(t, filepath.Join(testHome, "AppData"))

