type File interface {
	fs.File

	// Name returns the name of the file as presented to Open.
	Name() string
	io.Writer
	io.WriterAt
	// ReadAt must be safe for concurrent calls from multiple
	// goroutines on the same handle, matching the [io.ReaderAt]
	// contract documented in package io. Callers performing
	// concurrent random-access reads on a shared File rely on
	// this; backings that cannot honour it must not satisfy
	// [billy.File].
	io.ReaderAt
	io.Seeker
	// Truncate the file.
	Truncate(size int64) error
}

// Locker abstracts the lock and unlock of a File within the filesystem. Not
// all filesystem implementations support it.
type Locker interface {
	// Lock locks the file like e.g. flock. It protects against access from
	// other processes.
	Lock() error
	// Unlock unlocks the file.
	Unlock() error
}

// Syncer interface can be implemented by filesystems that support syncing.
type Syncer interface {
	// Sync commits the current contents of the file to stable storage.
	Sync() error
}

// Capable interface can return the available features of a filesystem.
type Capable interface {
	// Capabilities returns the capabilities of a filesystem in bit flags.
	Capabilities() Capability
}

// Capabilities returns the features supported by a filesystem. If the FS
// does not implement Capable interface it returns all features.

